.MODEL small
.STACK
.DATA
    string db ?
.CODE
    ;description
    main PROC
        getChar:
            mov AH,1h
            int 21h

            cmp AL,32d
            je fine

            mov string[SI],AL
            inc SI
            jmp getChar
        fine:
            mov AH,2h
            mov DL,string[SI]
            int 21h

            inc DI

            cmp DI,SI
            je fin
            jmp fine
        fin:

        .EXIT
    main ENDP

end main